CREATE TABLE loyalty_member (
  card_no VARCHAR(12),
  member_name VARCHAR(80),
  joined_on DATE,
  PRIMARY KEY (card_no)
);

CREATE TABLE pos_item (
  item_code VARCHAR(20),
  item_desc VARCHAR(100),
  sell_unit VARCHAR(10),
  PRIMARY KEY (item_code)
);

CREATE TABLE receipt (
  receipt_no VARCHAR(16),
  branch_name VARCHAR(60),
  receipt_ts DATETIME,
  customer_type ENUM,
  card_no VARCHAR(12),
  panel_company_text VARCHAR(80),
  status ENUM,
  updated_at DATETIME,
  PRIMARY KEY (receipt_no),
  FOREIGN KEY (card_no) REFERENCES loyalty_member (card_no)
);

CREATE TABLE receipt_line (
  receipt_no VARCHAR(16),
  line_no SMALLINT,
  item_code VARCHAR(20),
  qty DECIMAL(8, 2),
  unit_price_pkr DECIMAL(10, 2),
  discount_pkr DECIMAL(10, 2),
  updated_at DATETIME,
  PRIMARY KEY (receipt_no, line_no),
  FOREIGN KEY (receipt_no) REFERENCES receipt (receipt_no),
  FOREIGN KEY (item_code) REFERENCES pos_item (item_code)
);
